/**
 * verify-v4-hook-sell.mjs — structural verification harness.
 * Decodes our built calldata with viem (the same decoder that reads real txs) and diffs
 * every field against the UI's ground-truth blob. PASS = structural equality on all fields.
 */
import { decodeFunctionData, encodeFunctionData, parseAbi, getAddress } from "viem";
import { readFileSync } from "fs";

process.chdir("/Users/lancepitman/accumulate-imd");
const { buildHookedPoolSellCalldata } = await import("../v4-hook-sell.mjs");

const EXEC_ABI = parseAbi(["function execute(bytes commands, bytes[] inputs, uint256 deadline) payable"]);

// UI ground-truth inputs (from the user's Uniswap UI paste)
const UI_PERMIT_INPUT = "";
const UI_SWAP_INPUT = "";

// Build ours: same sell (1 IMD), same minOut, fresh sig — then decode both and diff.
const built = buildHookedPoolSellCalldata({
  tokenAddress: "0xd34a99bc0f67ae1bbd63c660e6d0b0dd03e263b7",
  amountHuman: "1",
  sellerAddress: "0xa71fb297aa443adfc22ff74981d8c067ec3475cb",
  minOutWei: BigInt("0x789adb2fe77fa"),
  permitSignature: {
    deadline: 1790127300n,
    expiration: 1790127300,
    nonce: 0,
    sig: "0x" + "d9".repeat(65),
  },
});

const oursDecoded = decodeFunctionData({ abi: EXEC_ABI, data: built.data });
const [ourCmds, ourInputs, ourDeadline] = oursDecoded.args;

console.log("commands: ours =", ourCmds, "| UI = 0x0a10", ourCmds === "0x0a10" ? "✓" : "✗");
console.log("inputs count: ours =", ourInputs.length, "| UI = 2", ourInputs.length === 2 ? "✓" : "✗");

// PERMIT input diff (word-level; sig bytes will differ, that's expected)
const ourPermit = ourInputs[0].slice(2);
const uiPermit = UI_PERMIT_INPUT.slice(2);
const permitWordsOurs = ourPermit.match(/.{64}/g);
const permitWordsUi = uiPermit.match(/.{64}/g);
console.log("\nPERMIT input: ours", permitWordsOurs.length, "words vs UI", permitWordsUi.length);
let permitOk = permitWordsOurs.length === permitWordsUi.length;
if (permitWordsOurs.length === permitWordsUi.length) {
  for (let i = 0; i < permitWordsOurs.length; i++) {
    if (permitWordsOurs[i] !== permitWordsUi[i]) {
      console.log(`  permit w${i} differs: ours=${permitWordsOurs[i]} ui=${permitWordsUi[i]}`);
    }
  }
  console.log("(only the 65-byte signature tail should differ)");
}

// SWAP input diff — field by field
const ourSwap = ourInputs[1].slice(2);
const uiSwap = UI_SWAP_INPUT.slice(2);
const swapOurs = ourSwap.match(/.{64}/g);
const swapUi = uiSwap.match(/.{64}/g);
console.log("\nSWAP input: ours", swapOurs.length, "words vs UI", swapUi.length);
if (swapOurs.length !== swapUi.length) {
  console.log("✗ LENGTH MISMATCH — encoding structure is wrong, cannot ship");
}
const labels = [
  "actions offset", "params offset", "actions len", "actions", "params count",
  "off[0]", "off[1]", "off[2]",
];
for (let i = 0; i < Math.min(swapOurs.length, swapUi.length); i++) {
  const match = swapOurs[i] === swapUi[i];
  const tag = i < labels.length ? labels[i] : "";
  console.log(`  w${i} ${match ? "=" : "≠"} ${tag} ${match ? "" : "ours=" + swapOurs[i] + " ui=" + swapUi[i]}`);
}
